CREATE   VIEW [synapse_ce].[vwRegulationActivity]
AS
SELECT 
	act.[activityid],
	act.[createdon],
	act.[createdby],
	act.[modifiedon],
	act.[modifiedby],
	act.[ownerid],
	act.[createdonbehalfby],
	act.[modifiedonbehalfby],
	act.[apuk_claimanttype],
	act.[apuk_timeclaimtype],
	act.[prioritycode],
	act.[instancetypecode],
	act.[deliveryprioritycode],
	act.[apuk_complaintreportsensitive],
	act.[isbilled],
	act.[apuk_typeofcost],
	act.[leftvoicemail],
	act.[ismapiprivate],
	act.[isregularactivity],
	act.[apuk_complaintreportrelevant],
	act.[apuk_complaintreportid],
	act.[sendermailboxid],
	act.[slaid],
	act.[slainvokedid],
	act.[serviceid],
	act.[customers],
	act.[partners],
	act.[resources],
	act.[from],
	act.[bcc],
	act.[to],
	act.[cc],
	act.[requiredattendees],
	act.[optionalattendees],
	act.[organizer],
	act.[regardingobjectid],
	act.[apuk_regulatoryroleid],
	rr.[apuk_name] AS [apuk_regulatoryroleidName],
	act.[transactioncurrencyid],
	act.[owningteam],
	act.[owningbusinessunit],
	act.[scheduledstart],
	act.[scheduledend],
	act.[apuk_reasonforcreation],
	act.[activitytypecode],
	act.[onholdtime],
	act.[lastonholdtime],
	act.[apuk_activitiesfortheowner],
	act.[description],
	act.[actualstart],
	act.[actualend],
	act.[actualdurationminutes],
	act.[subject],
	act.[apuk_startdateofclaim],
	act.[apuk_totaltimecost],
	act.[apuk_totaltimecost_base],
	act.[seriesid],
	act.[traversedpath],
	act.[exchangerate],
	act.[exchangeitemid],
	act.[statecode],
	act.[statuscode],
	act.[apuk_noofunits]
FROM synapse_ce.apuk_regulationactivity act
	LEFT JOIN synapse_ce.apuk_regulatoryrole rr
		ON act.[apuk_regulatoryroleid] = rr.[apuk_regulatoryroleid]
